mapper.select:

/* authsvc.UserManagementMapper.existsUser(사용자 존재 여부) */
SELECT EXISTS (
    SELECT 1
    FROM USERS
    WHERE USER_ID = #{userId}
)


/* authsvc.UserManagementMapper.findRoleIdsByName(역할 이름 기준 역할 ID 조회) */
SELECT ROLE_ID
FROM ROLES
WHERE ROLE_NAME = #{roleName}
ORDER BY ROLE_ID

mapper.insert:

/* authsvc.UserManagementMapper.insertUser(사용자 등록) */
INSERT INTO USERS (
    USER_ID
    ,USER_NM
    ,POSIT_DIV_NAME
    ,DEPT_NAME
    ,USER_PWD
    ,CREATED_BY
    ,CREATED_AT
    ,UPDATED_BY
    ,UPDATED_AT
)
VALUES (
    #{request.data.usrId}
    ,#{request.data.usrNm}
    ,#{request.data.positDivName}
    ,#{request.data.deptName}
    ,#{request.data.usrPwd}
    ,#{createdBy}
    ,current_timestamp
    ,#{createdBy}
    ,current_timestamp
)


/* authsvc.UserManagementMapper.insertUserRole(사용자 기본 역할 등록) */
INSERT INTO USER_ROLES (
    USER_ID
    ,ROLE_ID
)
VALUES (
    #{userId}
    ,#{roleId}
)

mapper.update:

/* authsvc.UserManagementMapper.updateUser(사용자 기본 정보 수정) */
UPDATE USERS
SET USER_NM = #{request.data.usrNm}
    ,POSIT_DIV_NAME = #{request.data.positDivName}
    ,DEPT_NAME = #{request.data.deptName}
    ,UPDATED_BY = #{updatedBy}
    ,UPDATED_AT = current_timestamp
WHERE USER_ID = #{userId}

mapper.delete:

/* authsvc.UserManagementMapper.deleteUserRoles(USERS 삭제 전에 USER_ROLES를 먼저 물리 삭제) */
DELETE FROM USER_ROLES
WHERE USER_ID = #{userId}


/* authsvc.UserManagementMapper.deleteUser(USER_ROLES 삭제 후에 USERS를 물리 삭제) */
DELETE FROM USERS
WHERE USER_ID = #{userId}
